238	#[cfg(test)]
239	mod tests {
240	    use super::*;
241	
242	    #[test]
243	    fn test_widget_creation() {
244	        let input = TextInput::new();
245	        let widget = TextInputWidget::new(&input);
246	        assert!(!widget.focused);
247	        assert!(!widget.disabled);
248	        assert!(!widget.masked);
249	    }
250	
251	    #[test]
252	    fn test_widget_builder() {
253	        let input = TextInput::with_text("test");
254	        let widget = TextInputWidget::new(&input)
255	            .title("Test Input")
256	            .placeholder("Enter text")
257	            .focused(true)
258	            .disabled(false)
259	            .masked(true);
260	
261	        assert!(widget.focused);
262	        assert!(!widget.disabled);
263	        assert!(widget.masked);
264	        assert_eq!(widget.title, Some("Test Input"));
265	        assert_eq!(widget.placeholder, Some("Enter text"));
266	    }
267	
268	    #[test]
269	    fn test_display_text_empty_with_placeholder() {
270	        let input = TextInput::new();
271	        let widget = TextInputWidget::new(&input).placeholder("Enter text...");
272	        assert_eq!(widget.display_text(), "Enter text...");
273	    }
274	
275	    #[test]
276	    fn test_display_text_normal() {
277	        let input = TextInput::with_text("hello");
278	        let widget = TextInputWidget::new(&input);
279	        assert_eq!(widget.display_text(), "hello");
280	    }
281	
282	    #[test]
283	    fn test_display_text_masked() {
284	        let input = TextInput::with_text("password123");
285	        let widget = TextInputWidget::new(&input).masked(true);
286	        assert_eq!(widget.display_text(), "•••••••••••");
287	        assert_eq!(widget.display_text().chars().count(), 11);
288	    }
289	
290	    #[test]
291	    fn test_text_style_disabled() {
292	        let input = TextInput::with_text("test");
293	        let widget = TextInputWidget::new(&input).disabled(true);
294	        // Just ensure it doesn't panic
295	        let _ = widget.text_style();
296	    }
297	
298	    #[test]
299	    fn test_border_style_focused() {
300	        let input = TextInput::new();
301	        let widget = TextInputWidget::new(&input).focused(true);
302	        // Just ensure it doesn't panic
303	        let _ = widget.border_style();
304	    }
