827	    /// Handle mouse events
828	    fn handle_mouse_event(&mut self, mouse: crossterm::event::MouseEvent) -> Result<ScreenAction> {
829	        // Don't handle mouse during processing
830	        if matches!(self.state.step, StorageSetupStep::Processing(_)) {
831	            return Ok(ScreenAction::None);
832	        }
833	
834	        match mouse.kind {
835	            MouseEventKind::Down(MouseButton::Left) => {
836	                // Check method list click
837	                if let Some(&idx) = self.method_regions.hit_test(mouse.column, mouse.row) {
838	                    if let Some(method) = StorageMethod::from_index(idx) {
839	                        self.state.method = method;
840	                        self.state.menu_state.select(Some(idx));
841	                        self.state.focus = StorageSetupFocus::MethodList;
842	                        return Ok(ScreenAction::Refresh);
843	                    }
844	                }
845	                // Check form field click
846	                if let Some(&field_idx) = self.form_field_regions.hit_test(mouse.column, mouse.row)
847	                {
848	                    self.state.focus = StorageSetupFocus::Form;
849	                    match self.state.method {
850	                        StorageMethod::GitHub => {
851	                            let field = match field_idx {
852	                                0 => GitHubField::Token,
853	                                1 => GitHubField::RepoName,
854	                                2 => GitHubField::RepoPath,
855	                                3 => GitHubField::Visibility,
856	                                _ => return Ok(ScreenAction::None),
857	                            };
858	                            self.state.github_field = field;
859	                        }
860	                        StorageMethod::Local => {
861	                            // Only one field in local mode
862	                        }
863	                    }
864	                    return Ok(ScreenAction::Refresh);
865	                }
866	            }
867	            MouseEventKind::ScrollUp => {
868	                if let Some(area) = self.method_pane_area {
869	                    if area.contains(ratatui::layout::Position::new(mouse.column, mouse.row)) {
870	                        // Only 2 items, just move to previous
871	                        if let Some(current) = self.state.menu_state.selected() {
872	                            if current > 0 {
873	                                self.state.menu_state.select(Some(current - 1));
874	                                if let Some(m) = StorageMethod::from_index(current - 1) {
875	                                    self.state.method = m;
876	                                }
877	                            }
878	                        }
879	                        return Ok(ScreenAction::Refresh);
880	                    }
881	                }
882	            }
883	            MouseEventKind::ScrollDown => {
884	                if let Some(area) = self.method_pane_area {
885	                    if area.contains(ratatui::layout::Position::new(mouse.column, mouse.row)) {
886	                        if let Some(current) = self.state.menu_state.selected() {
887	                            let max = StorageMethod::all().len().saturating_sub(1);
888	                            if current < max {
889	                                self.state.menu_state.select(Some(current + 1));
890	                                if let Some(m) = StorageMethod::from_index(current + 1) {
891	                                    self.state.method = m;
892	                                }
893	                            }
894	                        }
895	                        return Ok(ScreenAction::Refresh);
896	                    }
897	                }
898	            }
899	            _ => {}
900	        }
901	        Ok(ScreenAction::None)
902	    }
