1141	    /// Handle form submission
1142	    fn handle_submit(&mut self) -> Result<ScreenAction> {
1143	        self.state.error_message = None;
1144	
1145	        // In reconfiguration mode, only allow token updates
1146	        if self.state.is_reconfiguring {
1147	            if self.state.method == StorageMethod::GitHub && self.state.is_editing_token {
1148	                // User is updating their token
1149	                let token = self.state.token_input.text_trimmed().to_string();
1150	
1151	                // Validate token (ghp_ for classic, github_pat_ for fine-grained)
1152	                if !token.starts_with("ghp_") && !token.starts_with("github_pat_") {
1153	                    self.state.error_message =
1154	                        Some("Token must start with 'ghp_' or 'github_pat_'".to_string());
1155	                    return Ok(ScreenAction::None);
1156	                }
1157	
1158	                // Update the token in config
1159	                return Ok(ScreenAction::UpdateGitHubToken { token });
1160	            }
1161	            // In reconfiguration mode but not editing token - show info
1162	            self.state.status_message =
1163	                Some("Storage already configured. Press Esc to go back.".to_string());
1164	            return Ok(ScreenAction::None);
1165	        }
1166	
1167	        match self.state.method {
1168	            StorageMethod::GitHub => {
1169	                let token = self.state.token_input.text_trimmed().to_string();
1170	                let repo_name = self.state.repo_name_input.text_trimmed().to_string();
1171	
1172	                // Validate token (ghp_ for classic, github_pat_ for fine-grained)
1173	                if !token.starts_with("ghp_") && !token.starts_with("github_pat_") {
1174	                    self.state.error_message =
1175	                        Some("Token must start with 'ghp_' or 'github_pat_'".to_string());
1176	                    return Ok(ScreenAction::None);
1177	                }
1178	
1179	                if repo_name.is_empty() {
1180	                    self.state.error_message = Some("Repository name required".to_string());
1181	                    return Ok(ScreenAction::None);
1182	                }
1183	
1184	                // Return action to start GitHub setup
1185	                Ok(ScreenAction::StartGitHubSetup {
1186	                    token,
1187	                    repo_name,
1188	                    is_private: self.state.is_private,
1189	                })
1190	            }
1191	            StorageMethod::Local => {
1192	                let path_str = self.state.local_path_input.text_trimmed();
1193	
1194	                if path_str.is_empty() {
1195	                    self.state.error_message = Some("Path required".to_string());
1196	                    return Ok(ScreenAction::None);
1197	                }
1198	
1199	                let expanded_path = crate::git::expand_path(path_str);
1200	                let validation = crate::git::validate_local_repo(&expanded_path);
1201	
1202	                if !validation.is_valid {
1203	                    self.state.error_message = validation.error_message;
1204	                    return Ok(ScreenAction::None);
1205	                }
1206	
1207	                // Load profiles from the repository
1208	                let profiles = crate::utils::ProfileManifest::load_or_backfill(&expanded_path)
1209	                    .map(|m| m.profiles.iter().map(|p| p.name.clone()).collect())
1210	                    .unwrap_or_default();
1211	
1212	                // If the repo uses the experimental SHA-256 object format, gate
1213	                // the setup behind a confirmation popup before committing (issue #35).
1214	                if validation.warning_message.is_some() {
1215	                    self.state.pending_sha256_repo = Some((expanded_path, profiles));
1216	                    return Ok(ScreenAction::Refresh);
1217	                }
1218	
1219	                Ok(ScreenAction::SaveLocalRepoConfig {
1220	                    repo_path: expanded_path,
1221	                    profiles,
1222	                })
1223	            }
1224	        }
1225	    }
