1262	                        } else {
1263	                            ScreenAction::Refresh
1264	                        }
1265	                    }
1266	                    Some(Action::Cancel | Action::Quit) => {
1267	                        self.state.pending_sha256_repo = None;
1268	                        ScreenAction::Refresh
1269	                    }
1270	                    _ => ScreenAction::None,
1271	                }
1272	            }
1273	            // Block background interaction while the modal is open.
1274	            Event::Mouse(_) => ScreenAction::None,
1275	            _ => ScreenAction::None,
1276	        }
1277	    }
