935	    /// Handle events when form is focused
936	    fn handle_form_event(
937	        &mut self,
938	        key: crossterm::event::KeyEvent,
939	        ctx: &ScreenContext,
940	    ) -> Result<ScreenAction> {
941	        use crossterm::event::{KeyCode, KeyModifiers};
942	
943	        // For plain character keys (no modifiers), ALWAYS insert the character first
944	        // This ensures vim bindings like h/l/q don't interfere with typing
945	        if let KeyCode::Char(c) = key.code {
946	            if !key
947	                .modifiers
948	                .intersects(KeyModifiers::CONTROL | KeyModifiers::ALT | KeyModifiers::SUPER)
949	            {
950	                // Check if we're in an editable text field
951	                let is_editable = match self.state.method {
952	                    StorageMethod::GitHub => {
953	                        // Visibility is a toggle, not editable
954	                        if self.state.github_field == GitHubField::Visibility {
955	                            false
956	                        } else if self.state.is_reconfiguring {
957	                            // Only token field in edit mode is editable
958	                            self.state.github_field == GitHubField::Token
959	                                && self.state.is_editing_token
960	                        } else {
961	                            // All text fields editable in fresh setup
962	                            true
963	                        }
964	                    }
965	                    StorageMethod::Local => !self.state.is_reconfiguring,
966	                };
967	
968	                if is_editable {
969	                    // Insert character into the appropriate field
970	                    match self.state.method {
971	                        StorageMethod::GitHub => match self.state.github_field {
972	                            GitHubField::Token => self.state.token_input.insert_char(c),
973	                            GitHubField::RepoName => self.state.repo_name_input.insert_char(c),
974	                            GitHubField::RepoPath => self.state.repo_path_input.insert_char(c),
975	                            GitHubField::Visibility => {} // Not a text field
976	                        },
977	                        StorageMethod::Local => self.state.local_path_input.insert_char(c),
978	                    }
979	                    return Ok(ScreenAction::None);
980	                }
981	            }
982	        }
983	
984	        let action = ctx.config.keymap.get_action(key.code, key.modifiers);
985	
986	        // Handle form submission
987	        if matches!(action, Some(Action::Confirm | Action::Save)) {
988	            // In reconfiguration mode, Enter on Token field toggles edit mode
989	            if self.state.is_reconfiguring
990	                && self.state.method == StorageMethod::GitHub
991	                && self.state.github_field == GitHubField::Token
992	                && !self.state.is_editing_token
993	            {
994	                // Enter edit token mode
995	                self.state.is_editing_token = true;
996	                self.state.token_input = TextInput::new(); // Clear for new input
997	                self.state.status_message = Some("Enter new token".to_string());
998	                return Ok(ScreenAction::None);
999	            }
1000	            return self.handle_submit();
1001	        }
1002	
1003	        // Handle cancel/back
1004	        if let Some(Action::Cancel | Action::Quit) = action {
1005	            // If editing token, cancel exits edit mode (not the form)
1006	            if self.state.is_editing_token {
1007	                self.state.is_editing_token = false;
1008	                self.state.status_message = None;
1009	                self.state.error_message = None;
1010	                // Restore the masked token display (we don't have original, just clear)
1011	                self.state.token_input = TextInput::with_text("••••••••••••••••••••");
1012	                return Ok(ScreenAction::None);
1013	            }
1014	            self.state.focus = StorageSetupFocus::MethodList;
1015	            self.state.error_message = None;
1016	            return Ok(ScreenAction::None);
1017	        }
1018	
1019	        // Handle MoveLeft to go back to menu (only for text fields at cursor position 0)
1020	        // Note: Visibility field uses MoveLeft/MoveRight for toggling, so we skip it here
1021	        if let Some(Action::MoveLeft) = action {
1022	            let should_go_back = match self.state.method {
1023	                StorageMethod::GitHub => match self.state.github_field {
1024	                    GitHubField::Token => self.state.token_input.cursor() == 0,
1025	                    GitHubField::RepoName => self.state.repo_name_input.cursor() == 0,
1026	                    GitHubField::RepoPath => self.state.repo_path_input.cursor() == 0,
1027	                    GitHubField::Visibility => false, // MoveLeft toggles visibility, doesn't exit
1028	                },
1029	                StorageMethod::Local => self.state.local_path_input.cursor() == 0,
1030	            };
1031	
1032	            if should_go_back {
1033	                self.state.focus = StorageSetupFocus::MethodList;
1034	                return Ok(ScreenAction::None);
1035	            }
1036	        }
1037	
1038	        match self.state.method {
1039	            StorageMethod::GitHub => self.handle_github_form_input(action),
1040	            StorageMethod::Local => self.handle_local_form_input(action),
1041	        }
1042	    }
